1	package main
2	
3	import (
4		"context"
5		"flag"
6		"fmt"
7		"net/http"
8		"os"
9		"os/signal"
10		"syscall"
11		"time"
12	
13		"github.com/prometheus/client_golang/prometheus/promhttp"
14	
15		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/apiserver"
16		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
17		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/extproc"
18		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/modelruntime"
19		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
20		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
21		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/tracing"
22		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/routerruntime"
23		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/startupstatus"
24	)
25	
26	type runtimeOptions struct {
27		configPath             string
28		certPath               string
29		kubeconfig             string
30		namespace              string
31		port                   int
32		apiPort                int
33		apiBind                string
34		managementAuthMode     string
35		managementRemoteExpose *bool
36		metricsPort            int
37		enableAPI              bool
38		secure                 bool
39		downloadOnly           bool
40	}
41	
42	func parseRuntimeOptions() runtimeOptions {
43		var (
44			configPath             = flag.String("config", "config/config.yaml", "Path to the configuration file")
45			port                   = flag.Int("port", 50051, "Port to listen on for gRPC ExtProc")
46			apiPort                = flag.Int("api-port", 8080, "Port to listen on for the router apiserver")
47			apiBind                = flag.String("api-bind", "", "Bind address for the router apiserver (default from config: 127.0.0.1)")
48			managementAuthMode     = flag.String("management-auth-mode", "", "Management API auth mode: bearer or disabled")
49			managementRemoteExpose = flag.Bool("management-remote-exposure", false, "Allow remote exposure of the management API (requires bearer auth tokens in config)")
50			metricsPort            = flag.Int("metrics-port", 9190, "Port for Prometheus metrics")
51			enableAPI              = flag.Bool("enable-api", true, "Enable the router apiserver")
52			secure                 = flag.Bool("secure", false, "Enable secure gRPC server with TLS")
53			certPath               = flag.String("cert-path", "", "Path to TLS certificate directory (containing tls.crt and tls.key)")
54			kubeconfig             = flag.String("kubeconfig", "", "Path to kubeconfig file (optional, uses in-cluster config if not specified)")
55			namespace              = flag.String("namespace", "default", "Kubernetes namespace to watch for CRDs")
56			downloadOnly           = flag.Bool("download-only", false, "Download required models and exit (useful for CI/testing)")
57		)
58		flag.Parse()
59	
60		return runtimeOptions{
61			configPath:             *configPath,
62			certPath:               *certPath,
63			kubeconfig:             *kubeconfig,
64			namespace:              *namespace,
65			port:                   *port,
66			apiPort:                *apiPort,
67			apiBind:                *apiBind,
68			managementAuthMode:     *managementAuthMode,
69			managementRemoteExpose: boolFlagOverride(flag.CommandLine, "management-remote-exposure", *managementRemoteExpose),
70			metricsPort:            *metricsPort,
71			enableAPI:              *enableAPI,
72			secure:                 *secure,
73			downloadOnly:           *downloadOnly,
74		}
75	}
76	
77	// boolFlagOverride returns a pointer to value only when the named flag was
78	// explicitly supplied on the command line. Otherwise nil so config defaults
79	// are preserved (e.g. management_api.remote_exposure: true).
80	func boolFlagOverride(fs *flag.FlagSet, name string, value bool) *bool {
81		set := false
82		fs.Visit(func(f *flag.Flag) {
83			if f.Name == name {
84				set = true
85			}
86		})
87		if !set {
88			return nil
89		}
90		return &value
91	}
92	
93	func initializeRuntimeLogger() {
94		if _, err := logging.InitLoggerFromEnv(); err != nil {
95			fmt.Fprintf(os.Stderr, "failed to initialize logger: %v\n", err)
96		}
97	}
98	
99	func loadRuntimeConfigOrFatal(configPath string) *config.RouterConfig {
100		if _, err := os.Stat(configPath); os.IsNotExist(err) {
101			logging.ComponentFatalEvent("router", "runtime_config_missing", map[string]interface{}{
102				"config_path": configPath,
103			})
104		}
105	
106		cfg, err := config.Parse(configPath)
107		if err != nil {
108			logging.ComponentFatalEvent("router", "runtime_config_load_failed", map[string]interface{}{
109				"config_path": configPath,
110				"error":       err.Error(),
111			})
112		}
113		logging.ComponentDebugEvent("router", "runtime_config_loaded", map[string]interface{}{
114			"config_path":    configPath,
115			"config_source":  cfg.ConfigSource,
116			"decision_count": len(cfg.Decisions),
117		})
118		return cfg
119	}
120	
121	func newStartupWriter(cfg *config.RouterConfig, configPath string) startupstatus.StatusWriter {
122		writer := buildStartupWriter(cfg, configPath)
123		writeStartupState(writer, startupstatus.State{
124			Phase:   "starting",
125			Ready:   false,
126			Message: "Router process booting...",
127		}, "Failed to write initial startup status")
128		return writer
129	}
130	
131	func buildStartupWriter(cfg *config.RouterConfig, configPath string) startupstatus.StatusWriter {
132		if cfg.StartupStatus.StoreBackend == "redis" && cfg.StartupStatus.Redis != nil {
133			rw, err := startupstatus.NewRedisWriter(startupstatus.RedisWriterConfig{
134				Address:  cfg.StartupStatus.Redis.Address,
135				Password: cfg.StartupStatus.Redis.Password,
136				DB:       cfg.StartupStatus.Redis.DB,
137			})
138			if err != nil {
139				logging.ComponentWarnEvent("router", "startup_status_redis_fallback", map[string]interface{}{
140					"error":    err.Error(),
141					"fallback": "file",
142				})
143				return startupstatus.NewFileWriter(configPath)
144			}
145			logging.ComponentEvent("router", "startup_status_backend", map[string]interface{}{
146				"backend": "redis",
147				"address": cfg.StartupStatus.Redis.Address,
148			})
149			return rw
150		}
151	
152		logging.ComponentWarnEvent("router", "startup_status_file_backend", map[string]interface{}{
153			"backend": "file",
154			"message": "Startup status using local file backend. Status is not shared across replicas or visible to the dashboard in containerized deployments. Set startup_status.store_backend: redis for production use.",
155		})
156		return startupstatus.NewFileWriter(configPath)
157	}
158	
159	func writeStartupState(writer startupstatus.StatusWriter, state startupstatus.State, warning string) {
160		if err := writer.Write(state); err != nil {
161			logging.ComponentWarnEvent("router", "startup_state_write_failed", map[string]interface{}{
162				"warning": warning,
163				"phase":   state.Phase,
164				"ready":   state.Ready,
165				"error":   err.Error(),
166			})
167		}
168	}
169	
170	func failStartup(writer startupstatus.StatusWriter, format string, args ...interface{}) {
171		message := fmt.Sprintf(format, args...)
172		_ = writer.Write(startupstatus.State{
173			Phase:   "error",
174			Ready:   false,
175			Message: message,
176		})
177		logging.ComponentFatalEvent("router", "startup_failed", map[string]interface{}{
178			"message": message,
179		})
180	}
181	
182	func ensureModelsDownloadedOrFatal(cfg *config.RouterConfig, writer startupstatus.StatusWriter) {
183		if err := ensureModelsDownloaded(cfg, writer); err != nil {
184			failStartup(writer, "Failed to ensure models are downloaded: %v", err)
185		}
186	}
187	
188	func exitIfDownloadOnly(downloadOnly bool) {
189		if !downloadOnly {
190			return
191		}
192	
193		logging.ComponentEvent("router", "download_only_complete", map[string]interface{}{
194			"mode": "download_only",
195		})
196		os.Exit(0)
197	}
198	
199	func initializeTracing(cfg *config.RouterConfig) func() {
200		if !cfg.Observability.Tracing.Enabled {
201			return func() {}
202		}
203	
204		tracingCfg := tracing.TracingConfig{
205			Enabled:               cfg.Observability.Tracing.Enabled,
206			Provider:              cfg.Observability.Tracing.Provider,
207			ExporterType:          cfg.Observability.Tracing.Exporter.Type,
208			ExporterEndpoint:      cfg.Observability.Tracing.Exporter.Endpoint,
209			ExporterInsecure:      cfg.Observability.Tracing.Exporter.Insecure,
210			SamplingType:          cfg.Observability.Tracing.Sampling.Type,
211			SamplingRate:          cfg.Observability.Tracing.Sampling.Rate,
212			ServiceName:           cfg.Observability.Tracing.Resource.ServiceName,
213			ServiceVersion:        cfg.Observability.Tracing.Resource.ServiceVersion,
214			DeploymentEnvironment: cfg.Observability.Tracing.Resource.DeploymentEnvironment,
215		}
216		if err := tracing.InitTracing(context.Background(), tracingCfg); err != nil {
217			logging.ComponentWarnEvent("router", "tracing_init_failed", map[string]interface{}{
218				"provider":          tracingCfg.Provider,
219				"exporter_type":     tracingCfg.ExporterType,
220				"exporter_endpoint": tracingCfg.ExporterEndpoint,
221				"error":             err.Error(),
222			})
223		}
224		return shutdownTracing
225	}
226	
227	func shutdownTracing() {
228		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
229		defer cancel()
230		if err := tracing.ShutdownTracing(shutdownCtx); err != nil {
231			logging.ComponentErrorEvent("router", "tracing_shutdown_failed", map[string]interface{}{
232				"error": err.Error(),
233			})
234		}
235	}
236	
237	func initializeWindowedMetricsIfEnabled(cfg *config.RouterConfig) {
238		if !cfg.Observability.Metrics.WindowedMetrics.Enabled {
239			return
240		}
241	
242		if err := metrics.InitializeWindowedMetrics(cfg.Observability.Metrics.WindowedMetrics); err != nil {
243			logging.ComponentWarnEvent("router", "windowed_metrics_init_failed", map[string]interface{}{
244				"error": err.Error(),
245			})
246			return
247		}
248		logging.ComponentEvent("router", "windowed_metrics_initialized", map[string]interface{}{
249			"mode": "load_balancing",
250		})
251	}
252	
253	func registerSignalHandler(shutdownHooks *[]func()) {
254		sigChan := make(chan os.Signal, 1)
255		signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
256	
257		go func() {
258			sig := <-sigChan
259			logging.ComponentEvent("router", "shutdown_signal_received", map[string]interface{}{
260				"signal": sig.String(),
261			})
262			for _, hook := range *shutdownHooks {
263				hook()
264			}
265			shutdownTracing()
266			os.Exit(0)
267		}()
268	}
269	
270	func startMetricsServerIfEnabled(cfg *config.RouterConfig, metricsPort int) {
271		metricsEnabled := true
272		if cfg.Observability.Metrics.Enabled != nil {
273			metricsEnabled = *cfg.Observability.Metrics.Enabled
274		}
275		if metricsPort <= 0 {
276			metricsEnabled = false
277		}
278		if !metricsEnabled {
279			logging.ComponentEvent("router", "metrics_server_disabled", map[string]interface{}{
280				"metrics_port": metricsPort,
281			})
282			return
283		}
284	
285		go func() {
286			http.Handle("/metrics", promhttp.Handler())
287			metricsAddr := fmt.Sprintf(":%d", metricsPort)
288			logging.ComponentEvent("router", "metrics_server_starting", map[string]interface{}{
289				"address": metricsAddr,
290			})
291			if err := http.ListenAndServe(metricsAddr, nil); err != nil {
292				logging.ComponentErrorEvent("router", "metrics_server_failed", map[string]interface{}{
293					"address": metricsAddr,
294					"error":   err.Error(),
295				})
296			}
297		}()
298	}
299	
300	func initializeRuntimeDependencies(
301		cfg *config.RouterConfig,
302		writer startupstatus.StatusWriter,
303		shutdownHooks *[]func(),
304		runtimeRegistry *routerruntime.Registry,
305	) modelruntime.EmbeddingRuntimeState {
306		writeStartupState(writer, startupstatus.State{
307			Phase:   "initializing_models",
308			Ready:   false,
309			Message: "Initializing embedding models and router dependencies...",
310		}, "Failed to write initialization startup status")
311	
312		embeddingState, err := modelruntime.PrepareRouterRuntime(context.Background(), cfg, modelruntime.PrepareRouterRuntimeOptions{
313			Component:                  "router",
314			MaxParallelism:             modelruntime.DefaultParallelism(5),
315			OnEvent:                    logRuntimeLifecycleEvent,
316			InitModalityClassifierFunc: extproc.InitModalityClassifier,
317		})
318		if err != nil {
319			failStartup(writer, "Failed to initialize runtime dependencies: %v", err)
320		}
321		writeStartupState(writer, startupstatus.State{
322			Phase:             "initializing_models",
323			Ready:             false,
324			Message:           "Runtime dependencies initialized. Starting router services...",
325			EmbeddingProvider: startupEmbeddingProviderStatus(embeddingState),
326		}, "Failed to write runtime dependency startup status")
327	
328		initializeVectorStoreIfEnabled(cfg, shutdownHooks, runtimeRegistry)
329		return embeddingState
330	}
331	
332	func startupEmbeddingProviderStatus(state modelruntime.EmbeddingRuntimeState) *startupstatus.EmbeddingProviderStatus {
333		provider := state.EmbeddingProvider
334		if provider == nil {
335			return nil
336		}
337		return &startupstatus.EmbeddingProviderStatus{
338			Mode:           provider.Mode,
339			Backend:        provider.Backend,
340			Model:          provider.Model,
341			Dimension:      provider.Dimension,
342			APIKeyEnv:      provider.APIKeyEnv,
343			APIKeyEnvSet:   cloneBoolPtr(provider.APIKeyEnvSet),
344			Healthy:        cloneBoolPtr(provider.Healthy),
345			LastProbeError: provider.LastProbeError,
346			LastCheckedAt:  provider.LastCheckedAt,
347		}
348	}
349	
350	func cloneBoolPtr(value *bool) *bool {
351		if value == nil {
352			return nil
353		}
354		clone := *value
355		return &clone
356	}
357	
358	func logRuntimeLifecycleEvent(event modelruntime.Event) {
359		if event.Status != modelruntime.TaskFailed && event.Status != modelruntime.TaskSkipped {
360			return
361		}
362		payload := map[string]interface{}{
363			"task":        event.Task,
364			"best_effort": event.BestEffort,
365		}
366		if event.Error != nil {
367			payload["error"] = event.Error.Error()
368		}
369		if event.Status == modelruntime.TaskSkipped {
370			logging.ComponentWarnEvent("router", "runtime_lifecycle_task_skipped", payload)
371			return
372		}
373		if event.BestEffort {
374			logging.ComponentWarnEvent("router", "runtime_lifecycle_task_failed", payload)
375			return
376		}
377		logging.ComponentErrorEvent("router", "runtime_lifecycle_task_failed", payload)
378	}
379	
380	func initializeVectorStoreIfEnabled(
381		cfg *config.RouterConfig,
382		shutdownHooks *[]func(),
383		runtimeRegistry *routerruntime.Registry,
384	) {
385		if cfg.VectorStore == nil || !cfg.VectorStore.Enabled {
386			return
387		}
388	
389		logging.ComponentEvent("router", "vector_store_init_started", map[string]interface{}{
390			"backend": cfg.VectorStore.BackendType,
391		})
392		if err := cfg.VectorStore.Validate(); err != nil {
393			logging.ComponentFatalEvent("router", "vector_store_config_invalid", map[string]interface{}{
394				"backend": cfg.VectorStore.BackendType,
395				"error":   err.Error(),
396			})
397		}
398		vectorStoreRuntime, err := routerruntime.NewVectorStoreRuntime(cfg)
399		if err != nil {
400			logging.ComponentFatalEvent("router", "vector_store_runtime_create_failed", map[string]interface{}{
401				"backend": cfg.VectorStore.BackendType,
402				"error":   err.Error(),
403			})
404		}
405		if runtimeRegistry != nil {
406			runtimeRegistry.SetVectorStoreRuntime(vectorStoreRuntime)
407		}
408		vectorStoreRuntime.LogInitialized("router", cfg)
409		registerVectorStoreShutdownHook(shutdownHooks, vectorStoreRuntime)
410	}
411	
412	func registerVectorStoreShutdownHook(
413		shutdownHooks *[]func(),
414		vectorStoreRuntime *routerruntime.VectorStoreRuntime,
415	) {
416		*shutdownHooks = append(*shutdownHooks, func() {
417			logging.ComponentEvent("router", "vector_store_shutdown_started", map[string]interface{}{})
418			if err := vectorStoreRuntime.Shutdown(); err != nil {
419				logging.ComponentErrorEvent("router", "vector_store_shutdown_failed", map[string]interface{}{
420					"error": err.Error(),
421				})
422			}
423		})
424	}
425	
426	func newExtProcServerOrFatal(
427		opts runtimeOptions,
428		writer startupstatus.StatusWriter,
429		runtimeRegistry *routerruntime.Registry,
430	) *extproc.Server {
431		server, err := extproc.NewServer(opts.configPath, opts.port, opts.secure, opts.certPath, runtimeRegistry)
432		if err != nil {
