1	package startupstatus
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"hash/fnv"
7		"os"
8		"path/filepath"
9		"sync"
10		"time"
11	)
12	
13	// State captures router startup readiness beyond process-level health.
14	type State struct {
15		Phase             string                   `json:"phase"`
16		Ready             bool                     `json:"ready"`
17		Message           string                   `json:"message,omitempty"`
18		DownloadingModel  string                   `json:"downloading_model,omitempty"`
19		PendingModels     []string                 `json:"pending_models,omitempty"`
20		ReadyModels       int                      `json:"ready_models,omitempty"`
21		TotalModels       int                      `json:"total_models,omitempty"`
22		EmbeddingProvider *EmbeddingProviderStatus `json:"embedding_provider,omitempty"`
23		UpdatedAt         string                   `json:"updated_at,omitempty"`
24	}
25	
26	// EmbeddingProviderStatus exposes redacted embedding provider runtime state.
27	type EmbeddingProviderStatus struct {
28		Mode           string `json:"mode,omitempty"`
29		Backend        string `json:"backend,omitempty"`
30		Model          string `json:"model,omitempty"`
31		Dimension      int    `json:"dimension,omitempty"`
32		APIKeyEnv      string `json:"api_key_env,omitempty"`
33		APIKeyEnvSet   *bool  `json:"api_key_env_set,omitempty"`
34		Healthy        *bool  `json:"healthy,omitempty"`
35		LastProbeError string `json:"last_probe_error,omitempty"`
36		LastCheckedAt  string `json:"last_checked_at,omitempty"`
37	}
38	
39	// StatusWriter persists startup state so the dashboard (or other consumers)
40	// can track router startup progress. Implementations include FileWriter
41	// (local JSON file) and RedisWriter (shared key in Redis).
42	type StatusWriter interface {
43		Write(state State) error
44	}
45	
46	var _ StatusWriter = (*FileWriter)(nil)
47	
48	// FileWriter persists startup state to a JSON file.
49	type FileWriter struct {
50		path string
51		mu   sync.Mutex
52	}
53	
54	var statusDirCache sync.Map
55	
56	// NewFileWriter creates a file-based StatusWriter using a router config path.
57	func NewFileWriter(configPath string) *FileWriter {
58		return &FileWriter{path: StatusPathFromConfigPath(configPath)}
59	}
60	
61	// StatusPathFromConfigPath returns the runtime status path, preferring the config
62	// directory when it is writable and otherwise falling back to a temp-owned path.
63	func StatusPathFromConfigPath(configPath string) string {
64		statusDir := runtimeStatusDirFromConfigPath(configPath)
65		return filepath.Join(statusDir, "router-runtime.json")
66	}
67	
68	func runtimeStatusDirFromConfigPath(configPath string) string {
69		if overrideDir := os.Getenv("VLLM_SR_RUNTIME_STATUS_DIR"); overrideDir != "" {
70			return overrideDir
71		}
72	
73		configDir := filepath.Dir(configPath)
74		cacheKey := filepath.Clean(configDir)
75		if cached, ok := statusDirCache.Load(cacheKey); ok {
76			return cached.(string)
77		}
78	
79		statusDir := filepath.Join(os.TempDir(), "vllm-sr", "runtime-status", stablePathToken(configDir))
80		if dirWritable(configDir) {
81			statusDir = configDir
82		}
83		statusDirCache.Store(cacheKey, statusDir)
84		return statusDir
85	}
86	
87	func dirWritable(path string) bool {
88		info, err := os.Stat(path)
89		if err != nil || !info.IsDir() {
